-- Renames the provisioning flag to `is_system`, aligning on the
-- convention already used by property_definitions.is_system /
-- image_packs.is_system (see apps/server/lib/archimate/store.ts).
ALTER TABLE "dashboards" RENAME COLUMN "is_provisioned" TO "is_system";
--> statement-breakpoint

-- System dashboards are shared by every workspace, not duplicated per
-- workspace: "workspace_id" is NULL for them, mirroring
-- image_packs.organization_id (see 0023_image_packs.sql). A workspace's
-- own custom dashboards keep "workspace_id" NOT NULL, unaffected.
ALTER TABLE "dashboards" ALTER COLUMN "workspace_id" DROP NOT NULL;
--> statement-breakpoint

CREATE UNIQUE INDEX "dashboards_system_dashboard_id_uniq" ON "dashboards" USING btree ("dashboard_id") WHERE "workspace_id" IS NULL;
--> statement-breakpoint

-- Seeds the fixed set of system dashboards, once, shared globally. This is
-- the only place that writes these rows — there is no runtime seed/reseed
-- path. If packages/db/seeds/dashboards.sql changes later (new dashboard,
-- new revision), regenerate the JSON below with parseSourceRevisions()
-- (packages/db/src/seed-dashboards-data.ts) and hand-write a new numbered
-- backfill migration.
INSERT INTO "dashboards" ("dashboard_id", "is_system", "latest_revision", "created_by_id")
VALUES
  ('demonstration-datasources', true, 1, 'system'),
  ('motivation', true, 1, 'system'),
  ('principles', true, 1, 'system'),
  ('rapports-application', true, 2, 'system'),
  ('rapports-architecture', true, 3, 'system'),
  ('voisinage-elements', true, 2, 'system'),
  ('vue-architecture-applicative', true, 2, 'system');
--> statement-breakpoint

INSERT INTO "dashboard_revisions" ("dashboard_id", "revision", "definition", "created_by_id")
SELECT dd."id", r."revision", r."definition"::jsonb, 'system'
FROM "dashboards" dd
JOIN (VALUES
  ('demonstration-datasources', 1, $def_demonstration_datasources_1${"id": "demonstration-datasources", "title": "Démonstration des datasources", "description": "Présente côte à côte une métrique Neo4j et une métrique PostgreSQL de démonstration.", "category": "Démonstration", "schemaVersion": 2, "parameters": [], "panels": [{"id": "elements-neo4j", "panel": {"title": "Éléments", "description": "Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.", "resultType": "metrics", "parameters": [], "visualization": {"type": "core/metric", "max": 1000}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (element:Element {organizationId: $organizationId}) RETURN count(element) AS count"}}, "layout": {"x": 0, "y": 0, "width": 6, "height": 3}, "parameterBindings": {}}, {"id": "fournisseurs-postgres", "panel": {"title": "Fournisseurs actifs (démonstration PostgreSQL)", "description": "Métrique issue du jeu de données PostgreSQL local de démonstration.", "resultType": "metrics", "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (element:Element {organizationId: $organizationId}) RETURN count(element) AS count"}, "parameters": [{"name": "actif", "label": "Fournisseurs actifs", "type": "boolean", "required": false, "defaultValue": true}], "visualization": {"type": "core/metric"}}, "layout": {"x": 6, "y": 0, "width": 6, "height": 3}, "parameterBindings": {}}], "createdAt": "2026-08-07T20:00:00.000Z", "updatedAt": "2026-08-07T20:00:00.000Z", "createdBy": "codex", "updatedBy": "codex"}$def_demonstration_datasources_1$),
  ('motivation', 1, $def_motivation_1${"id": "motivation", "title": "Chaîne de motivation par driver", "description": "Affiche les Drivers, Assessments, Goals et Outcomes reliés au driver sélectionné.", "category": "Motivation", "schemaVersion": 2, "parameters": [{"name": "driverId", "label": "Driver", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["Driver"]}}], "panels": [{"id": "chaine-motivation", "panel": {"title": "Chaîne de motivation par driver", "description": "Affiche les Drivers, Assessments, Goals et Outcomes reliés au driver sélectionné.", "resultType": "graph", "parameters": [{"name": "driverId", "label": "Driver", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["Driver"]}}], "visualization": {"colorByProperty": "type", "type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (driver:Element {organizationId: $organizationId, id: $driverId, type: 'Driver'})\nOPTIONAL MATCH path = (driver)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..5]-(target:Element {organizationId: $organizationId})\nWHERE target.type IN ['Assessment', 'Goal', 'Outcome']\n  AND all(node IN nodes(path) WHERE node.type IN ['Driver', 'Assessment', 'Goal', 'Outcome'])\nWITH driver, reduce(allNodes = [driver], pathNodes IN collect(nodes(path)) | allNodes + coalesce(pathNodes, [])) AS pathNodes\nUNWIND pathNodes AS node\nWITH driver, node WHERE node IS NOT NULL\nRETURN collect(DISTINCT node.id) AS nodeIds, driver.id AS emphasizedId"}}, "layout": {"x": 0, "y": 0, "width": 12, "height": 8}, "parameterBindings": {"driverId": {"source": "dashboard", "parameter": "driverId"}}}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-07T00:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "christophe.lacombe"}$def_motivation_1$),
  ('principles', 1, $def_principles_1${"id": "principles", "title": "Chaîne de conformité par principe", "description": "Affiche le principe sélectionné et les exigences et contraintes qui lui sont reliées.", "category": "Motivation", "schemaVersion": 2, "parameters": [{"name": "principleId", "label": "Principe", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["Principle"]}}], "panels": [{"id": "chaine-conformite", "panel": {"title": "Chaîne de conformité par principe", "description": "Affiche le principe sélectionné et les exigences et contraintes qui lui sont reliées.", "resultType": "graph", "parameters": [{"name": "principleId", "label": "Principe", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["Principle"]}}], "visualization": {"colorByProperty": "type", "type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (principle:Element {organizationId: $organizationId, id: $principleId, type: 'Principle'})\nOPTIONAL MATCH constraintPath = (principle)--(requirement:Element {organizationId: $organizationId, type: 'Requirement'})--(constraint:Element {organizationId: $organizationId, type: 'Constraint'})\nWITH principle, [pathNodes IN collect(nodes(constraintPath)) WHERE pathNodes IS NOT NULL] AS constraintPaths\nOPTIONAL MATCH (principle)--(directRequirement:Element {organizationId: $organizationId, type: 'Requirement'})\nWITH principle, constraintPaths, collect(DISTINCT directRequirement) AS directRequirements\nWITH principle, CASE\n  WHEN size(constraintPaths) > 0\n  THEN reduce(allNodes = [], pathNodes IN constraintPaths | allNodes + pathNodes)\n  ELSE [principle] + directRequirements\nEND AS selectedNodes\nUNWIND selectedNodes AS node\nRETURN collect(DISTINCT node.id) AS nodeIds, principle.id AS emphasizedId"}}, "layout": {"x": 0, "y": 0, "width": 12, "height": 8}, "parameterBindings": {"principleId": {"source": "dashboard", "parameter": "principleId"}}}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-07T00:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "christophe.lacombe"}$def_principles_1$),
  ('rapports-application', 1, $def_rapports_application_1${"id": "rapports-application", "title": "Rapports application", "description": "Acteurs métier, fonctions, technologies et exigences d’une application.", "category": "Applications", "schemaVersion": 2, "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["ApplicationComponent"]}}], "panels": [{"id": "acteurs-metier", "panel": {"title": "Acteurs métier (voisinage applicatif)", "description": "Acteurs et rôles métier atteints depuis un composant applicatif donné, jusqu'à 2 sauts.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Identifiant de l'application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..2]-(target:Element {organizationId: $organizationId})\nWHERE target.type IN ['BusinessActor', 'BusinessRole']\nWITH DISTINCT target LIMIT 500\nRETURN collect(target.id) AS nodeIds"}}, "layout": {"x": 0, "y": 0, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "fonctions-metier", "panel": {"title": "Fonctions métier", "description": "Composants applicatifs directement liés à l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (root:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..1]-(other:Element {organizationId: $organizationId, type: 'ApplicationComponent'})\nWITH root, collect(DISTINCT other.id) AS others\nRETURN others + [root.id] AS nodeIds, root.id AS emphasizedId"}}, "layout": {"x": 6, "y": 0, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "composants-technologiques", "panel": {"title": "Composants technologiques", "description": "Éléments technologiques documentés comme appartenant à l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (app:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {organizationId: $organizationId, layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\nWITH [item IN collect(DISTINCT tech) WHERE item IS NOT NULL | item] AS techs\nUNWIND CASE WHEN size(techs) = 0 THEN [null] ELSE techs END AS tech\nWITH techs, collect(CASE\n  WHEN tech IS NULL THEN null\n  WHEN tech.type = 'CommunicationNetwork' AND NOT EXISTS { MATCH (tech)-[:COMPOSITION|AGGREGATION]->(:Element {organizationId: $organizationId, type: 'CommunicationNetwork'}) } THEN {id: tech.id, rankGroup: 'subnet'}\n  WHEN tech.type = 'TechnologyInterface' THEN {id: tech.id, rankGroup: 'private-endpoint'}\n  ELSE null END) AS rawRankGroups\nRETURN [tech IN techs | tech.id] AS nodeIds, [item IN rawRankGroups WHERE item IS NOT NULL | item] AS rankGroups"}}, "layout": {"x": 0, "y": 7, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "traceabilite-exigences", "panel": {"title": "Traçabilité des exigences", "description": "Exigences réalisées par les composants technologiques de l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (app:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {organizationId: $organizationId, layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\n               WHERE (tech)-[:REALIZATION]->(:Element {organizationId: $organizationId, type: 'Requirement', layer: 'Motivation'})\nOPTIONAL MATCH (tech)-[:REALIZATION]->(requirement:Element {organizationId: $organizationId, type: 'Requirement', layer: 'Motivation'})\nWITH collect(DISTINCT tech.id) AS techIds, collect(DISTINCT requirement.id) AS requirementIds\nRETURN [id IN techIds + requirementIds WHERE id IS NOT NULL | id] AS nodeIds"}}, "layout": {"x": 6, "y": 7, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-07T00:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "christophe.lacombe"}$def_rapports_application_1$),
  ('rapports-application', 2, $def_rapports_application_2${"id": "rapports-application", "title": "Rapports application", "description": "Acteurs métier, fonctions, technologies et exigences d’une application.", "category": "Applications", "schemaVersion": 2, "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["ApplicationComponent"]}}], "panels": [{"id": "acteurs-metier", "panel": {"title": "Acteurs métier (voisinage applicatif)", "description": "Acteurs et rôles métier atteints depuis un composant applicatif donné, jusqu'à 2 sauts.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Identifiant de l'application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..2]-(target:Element {organizationId: $organizationId})\nWHERE target.type IN ['BusinessActor', 'BusinessRole']\nWITH DISTINCT target LIMIT 500\nRETURN collect(target.id) AS nodeIds"}}, "layout": {"x": 0, "y": 0, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "fonctions-metier", "panel": {"title": "Fonctions métier", "description": "Composants applicatifs directement liés à l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (root:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..1]-(other:Element {organizationId: $organizationId, type: 'ApplicationComponent'})\nWITH root, collect(DISTINCT other.id) AS others\nRETURN others + [root.id] AS nodeIds, root.id AS emphasizedId"}}, "layout": {"x": 6, "y": 0, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "composants-technologiques", "panel": {"title": "Composants technologiques", "description": "Éléments technologiques documentés comme appartenant à l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (app:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {organizationId: $organizationId, layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\nWITH [item IN collect(DISTINCT tech) WHERE item IS NOT NULL | item] AS techs\nUNWIND CASE WHEN size(techs) = 0 THEN [null] ELSE techs END AS tech\nWITH techs, collect(CASE\n  WHEN tech IS NULL THEN null\n  WHEN tech.type = 'CommunicationNetwork' AND NOT EXISTS { MATCH (tech)-[:COMPOSITION|AGGREGATION]->(:Element {organizationId: $organizationId, type: 'CommunicationNetwork'}) } THEN {id: tech.id, rankGroup: 'subnet'}\n  WHEN tech.type = 'TechnologyInterface' THEN {id: tech.id, rankGroup: 'private-endpoint'}\n  ELSE null END) AS rawRankGroups\nRETURN [tech IN techs | tech.id] AS nodeIds, [item IN rawRankGroups WHERE item IS NOT NULL | item] AS rankGroups"}}, "layout": {"x": 0, "y": 7, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "traceabilite-exigences", "panel": {"title": "Traçabilité des exigences", "description": "Exigences réalisées par les composants technologiques de l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (app:Element {organizationId: $organizationId, id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {organizationId: $organizationId, layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\n               WHERE (tech)-[:REALIZATION]->(:Element {organizationId: $organizationId, type: 'Requirement', layer: 'Motivation'})\nOPTIONAL MATCH (tech)-[:REALIZATION]->(requirement:Element {organizationId: $organizationId, type: 'Requirement', layer: 'Motivation'})\nWITH collect(DISTINCT tech.id) AS techIds, collect(DISTINCT requirement.id) AS requirementIds\nRETURN [id IN techIds + requirementIds WHERE id IS NOT NULL | id] AS nodeIds"}}, "layout": {"x": 6, "y": 7, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-07T00:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "christophe.lacombe"}$def_rapports_application_2$),
  ('rapports-architecture', 1, $def_rapports_architecture_1${"id": "rapports-architecture", "title": "Rapports d’Architecture", "description": "Vue d’ensemble du modèle ArchiMate courant.", "category": "Architecture", "schemaVersion": 2, "parameters": [], "panels": [{"id": "elements", "panel": {"title": "Éléments", "description": "Nombre total d’éléments ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (element:Element {organizationId: $organizationId}) RETURN count(element) AS count"}}, "layout": {"x": 0, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "relations", "panel": {"title": "Relations", "description": "Nombre total de relations ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (:Element {organizationId: $organizationId})-[relationship]->(:Element {organizationId: $organizationId}) RETURN count(relationship) AS count"}}, "layout": {"x": 3, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "vues", "panel": {"title": "Vues", "description": "Nombre total de vues ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (view:View {organizationId: $organizationId}) RETURN count(view) AS count"}}, "layout": {"x": 6, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "couches", "panel": {"title": "Couches ArchiMate", "description": "Nombre de couches présentes dans le modèle.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (element:Element {organizationId: $organizationId}) RETURN count(DISTINCT element.layer) AS count"}}, "