  ('rapports-architecture', 3, $def_rapports_architecture_3${"id": "rapports-architecture", "title": "Rapports d’Architecture", "description": "Vue d’ensemble du modèle ArchiMate courant.", "category": "Architecture", "schemaVersion": 2, "parameters": [], "panels": [{"id": "elements", "panel": {"title": "Éléments", "description": "Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.", "resultType": "metrics", "parameters": [], "visualization": {"type": "core/metric", "max": 1000}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (element:Element {organizationId: $organizationId}) RETURN count(element) AS count"}}, "layout": {"x": 0, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "relations", "panel": {"title": "Relations", "description": "Nombre total de relations ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (:Element {organizationId: $organizationId})-[relationship]->(:Element {organizationId: $organizationId}) RETURN count(relationship) AS count"}}, "layout": {"x": 3, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "vues", "panel": {"title": "Vues", "description": "Nombre total de vues ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (view:View {organizationId: $organizationId}) RETURN count(view) AS count"}}, "layout": {"x": 6, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "couches", "panel": {"title": "Couches ArchiMate", "description": "Nombre de couches présentes dans le modèle.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (element:Element {organizationId: $organizationId}) RETURN count(DISTINCT element.layer) AS count"}}, "layout": {"x": 9, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}], "createdAt": "2026-08-07T16:30:00.000Z", "updatedAt": "2026-08-07T16:30:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "christophe.lacombe"}$def_rapports_architecture_3$),
  ('voisinage-elements', 1, $def_voisinage_elements_1${"id": "voisinage-elements", "title": "Voisinage des éléments", "description": "Explorez les relations directes de l’élément sélectionné.", "category": "Éléments", "schemaVersion": 2, "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["Stakeholder", "Driver", "Assessment", "Goal", "Outcome", "Principle", "Requirement", "Constraint", "Meaning", "Value", "Resource", "Capability", "CourseOfAction", "ValueStream", "BusinessActor", "BusinessRole", "BusinessCollaboration", "BusinessInterface", "BusinessProcess", "BusinessFunction", "BusinessInteraction", "BusinessEvent", "BusinessService", "BusinessObject", "Contract", "Representation", "Product", "ApplicationComponent", "ApplicationCollaboration", "ApplicationInterface", "ApplicationFunction", "ApplicationInteraction", "ApplicationProcess", "ApplicationEvent", "ApplicationService", "DataObject", "Node", "Device", "SystemSoftware", "TechnologyCollaboration", "TechnologyInterface", "Path", "CommunicationNetwork", "TechnologyFunction", "TechnologyProcess", "TechnologyInteraction", "TechnologyEvent", "TechnologyService", "Artifact", "Equipment", "Facility", "DistributionNetwork", "Material", "WorkPackage", "Deliverable", "ImplementationEvent", "Plateau", "Gap", "Location", "Grouping"]}}], "panels": [{"id": "graphe-voisinage", "panel": {"title": "Voisinage de l’élément", "description": "Relations directes de l’élément sélectionné, dans les deux sens.", "resultType": "graph", "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (root:Element {organizationId: $organizationId, id: $elementId})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION]-(neighbor:Element {organizationId: $organizationId})\nWITH root, collect(DISTINCT neighbor.id)[0..99] AS neighborIds\nRETURN neighborIds + root.id AS nodeIds, root.id AS emphasizedId"}}, "layout": {"x": 0, "y": 0, "width": 12, "height": 8}, "parameterBindings": {"elementId": {"source": "dashboard", "parameter": "elementId"}}}, {"id": "proprietes", "panel": {"title": "Propriétés", "description": "Propriétés ArchiMate de l’élément sélectionné.", "resultType": "table", "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true}], "visualization": {"type": "table"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (root:Element {organizationId: $organizationId, id: $elementId})\nOPTIONAL MATCH (root)-[:HAS_PROPERTY]->(property:Property)\nWITH [item IN collect(property) WHERE item IS NOT NULL | {Nom: item.name, Valeur: item.value}] AS rows\nRETURN rows"}}, "layout": {"x": 0, "y": 8, "width": 12, "height": 5}, "parameterBindings": {"elementId": {"source": "dashboard", "parameter": "elementId"}}}, {"id": "relations", "panel": {"title": "Relations", "description": "Relations entrantes et sortantes de l’élément sélectionné.", "resultType": "table", "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true}], "visualization": {"columnOrder": ["Direction", "Relation", "Élément", "Type", "Couche"], "type": "table"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (root:Element {organizationId: $organizationId, id: $elementId})\nOPTIONAL MATCH (root)-[relationship]-(other:Element {organizationId: $organizationId})\nWHERE relationship IS NULL OR type(relationship) <> 'HAS_PROPERTY'\nWITH root, [item IN collect(CASE WHEN relationship IS NULL THEN null ELSE {Direction: CASE WHEN startNode(relationship) = root THEN 'Sortante' ELSE 'Entrante' END, Relation: relationship.archiType, `Élément`: other.name, Type: other.type, Couche: other.layer} END) WHERE item IS NOT NULL] AS rows\nRETURN rows"}}, "layout": {"x": 0, "y": 8, "width": 12, "height": 5}, "parameterBindings": {"elementId": {"source": "dashboard", "parameter": "elementId"}}}], "tabGroups": [{"id": "details-element", "tabs": [{"id": "proprietes", "title": "Propriétés", "panelIds": ["proprietes"]}, {"id": "relations", "title": "Relations", "panelIds": ["relations"]}]}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-07T00:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "christophe.lacombe"}$def_voisinage_elements_1$),
