  ('vue-architecture-applicative', 1, $def_vue_architecture_applicative_1${"id": "vue-architecture-applicative", "title": "Vue d’ensemble applicative", "description": "Synthèse des composants applicatifs, de leur documentation et des acteurs métier servis.", "category": "Applications", "schemaVersion": 2, "parameters": [], "panels": [{"id": "composants-connectes", "panel": {"title": "Composants applicatifs connectés par des flux", "description": "Composants applicatifs atteints par un flux direct depuis un autre composant applicatif.", "resultType": "graph", "parameters": [], "visualization": {"type": "graph"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (:Element {organizationId: $organizationId, type: 'ApplicationComponent'})-[:FLOW]->(target:Element {organizationId: $organizationId, type: 'ApplicationComponent'})\nWHERE target.name IS NOT NULL\nWITH DISTINCT target ORDER BY target.name ASC LIMIT 100\nRETURN collect(target.id) AS nodeIds"}}, "layout": {"x": 0, "y": 0, "width": 9, "height": 7}, "parameterBindings": {}}, {"id": "sans-documentation", "panel": {"title": "Composants applicatifs sans documentation", "description": "Nombre de composants applicatifs sans documentation renseignée.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "architecture-neo4j", "language": "cypher", "text": "MATCH (target:Element {organizationId: $organizationId, type: 'ApplicationComponent'})\nWHERE target.documentation IS NULL\nWITH DISTINCT target LIMIT 500\nRETURN count(target) AS count"}}, "layout": {"x": 9, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "acteurs-servis", "panel": {"title": "Acteurs métier servis par les composants applicatifs", "description": "Liste chaque composant applicatif et les acteurs métier qu'il sert directement.", "resultType": "table", "parameters": [{"name": "couche", "label": "Couche ArchiMate", "type": "enum", "required": false, 